D=[
("circumspect","LATIN ORIGIN",[("circum-","around","周圍","a circle of arrows going around"),("specere","to look","看","a big open eye")],("look all around before acting → cautious","謹慎的；小心周到的"),"before crossing a street, a careful boy looks left, right, and behind him with binoculars while his friend waits at the crosswalk.","Look around before you go,","Circumspect and careful, slow."),
("quiescent","LATIN ORIGIN",[("quies","rest, quiet","休息、安靜","a sleeping moon with Zzz"),("-escere","becoming, being","變得…","a slowing clock")],("resting, still for now → inactive","靜止的；暫時不活動的"),"a big volcano sleeps peacefully with a nightcap and Zzz, while children picnic safely on the green slope below.","The volcano sleeps without a sound,","Quiescent now, but still around."),
("foible","OLD FRENCH ORIGIN",[("faible / foible","weak","弱的","a bent, wobbly arm"),("fencing","the weak part of a sword blade","劍身較弱的部分","a sword with its tip end glowing")],("a small weak spot → a minor fault or odd habit","小缺點；怪癖"),"a superhero kid with a cape is brave and strong, but always wears mismatched socks and hums loudly while eating; friends smile kindly.","Everyone has a quirky way,","A foible makes us smile all day."),
("fervent","LATIN ORIGIN",[("fervere","to boil, glow","沸騰、發熱","a bubbling pot over fire"),("-ent","being, doing","…的","a glowing heart")],("boiling with feeling → passionate","熱烈的；熱忱的"),"a fan at a school basketball game cheers wildly with a painted face and a waving flag, steam rising from his excited head.","Hearts that boil and spirits glow,","Fervent fans cheer row by row."),
("protract","LATIN ORIGIN",[("pro-","forward","向前","an arrow pointing forward"),("trahere","to drag, pull","拖、拉","a rope being pulled")],("drag forward → make longer","延長；拖延"),"a boy pulls a super long piece of chewing gum, stretching it across the whole classroom, while a wall clock ticks on and on.","Drag it out and pull it long,","Protract the meeting, sing the song."),
("ostentatious","LATIN ORIGIN",[("ob-","in front of","在…前面","a person standing at the front"),("tendere","to stretch, hold out","伸展、伸出","a hand stretching out")],("stretch out in front of people → show off","炫耀的；鋪張浮誇的"),"a boy arrives at school in a golden car, wearing sunglasses, a sparkling crown, and a huge gold chain, waving to everyone.","Gold and glitter, look at me,","Ostentatious as can be."),
("quandary","LATIN ORIGIN (?)",[("quando?","when? (perhaps)","何時？","a clock with a question mark"),("-ary","a state of","…的狀態","a person standing at a fork")],("\"when? what now?\" → stuck, not knowing what to do","困惑；進退兩難的處境"),"a girl stands at a fork in a forest path holding two signs, 'Party' and 'Study', scratching her head with question marks above.","Which way now? I cannot say,","A quandary blocks my way."),
("censure","LATIN ORIGIN",[("censere","to assess, judge","評估、判斷","a judge's gavel"),("-ura","the act of","…的行為","a pointing finger")],("a formal judgment → strong criticism","譴責；嚴厲批評"),"a school council sits at a long desk, frowning and pointing at a student who littered, holding up a big red 'X' card.","Judge it wrong and say it loud,","Censure comes before the crowd."),
("cavil","LATIN ORIGIN",[("cavilla","a jest, a trick in words","玩笑、詭辯","a jester's hat"),("cavillari","to jeer, quibble","嘲弄、挑剔","a magnifying glass over a tiny dot")],("tease and nitpick → raise petty objections","挑剔；吹毛求疵"),"a picky critic uses a giant magnifying glass to point at one tiny crumb on a beautiful birthday cake while everyone else claps.","Tiny faults he loves to find,","Cavil, cavil, never kind."),
("assimilate","LATIN ORIGIN",[("ad-","to, toward","向","an arrow"),("similis","similar, like","相似的","two matching puzzle pieces")],("make similar → absorb and blend in","吸收；同化"),"a sponge-shaped student happily soaks up floating letters, numbers, and pictures from open books around him.","Take it in and make it mine,","Assimilate, fit in fine."),
("rescind","LATIN ORIGIN",[("re-","back","回","a U-turn arrow"),("scindere","to cut","切","scissors")],("cut back → cancel officially","廢除；撤銷"),"a principal cuts an old 'No Recess' rule paper in half with giant scissors, and students cheer.","Cut it back and set it free,","Rescind the rule by decree."),
("discernible","LATIN ORIGIN",[("dis-","apart","分開","two arrows pointing apart"),("cernere","to sift, separate","篩選、分辨","a sieve sifting sand"),("-ible","able to be","可…的","a check mark")],("able to be sifted out → can be seen or noticed","可辨別的；看得出的"),"in thick fog, a hiker spots the faint but clear outline of a lighthouse; one gold coin also shines in a sieve of sand.","Sift it out and you will see,","Discernible clear as can be."),
("cataclysm","GREEK ORIGIN",[("kata-","down","向下","a downward arrow"),("klyzein","to wash","沖洗","big crashing waves")],("washed down → a great flood or disaster","大災難；劇變"),"a giant wave crashes over a model city on a classroom table during a science demo; toy houses tumble while students gasp safely behind glass.","Water crashes, cities fall,","A cataclysm changes all."),
("narcissism","GREEK ORIGIN",[("Narkissos","a youth in Greek myth who loved his reflection","愛上自己倒影的少年","a boy gazing into a pond"),("-ism","a condition, habit","…主義、狀態","a mirror")],("loving your own reflection → too much self-love","自戀；自我陶醉"),"a boy kneels by a pond, staring lovingly at his own reflection with hearts around it, ignoring friends who call him to play.","In the pond he loves his face,","Narcissism takes first place."),
("incriminate","LATIN ORIGIN",[("in-","into","進入","an arrow going in"),("crimen","crime, charge","罪行、指控","a broken window")],("put into a crime → make someone seem guilty","使負罪；使（某人）涉入罪嫌"),"a cartoon dog sits next to a chewed-up shoe with shoe pieces on its nose, while a detective points a magnifying glass at the paw prints.","Clues point in, the proof is clear,","Incriminate the culprit here."),
("stigma","GREEK ORIGIN",[("stizein","to prick, tattoo","刺、刺上記號","a sharp pointed pen"),("stigma","a mark made by pricking","刺出的記號","a dark mark on a shirt")],("a pricked mark → a mark of shame","恥辱；汙名"),"a sad cartoon apple with a dark spot sits alone in a fruit bowl; other fruits leave it out, but a kind banana comes over to be friends.","A mark that others wrongly see,","Stigma hurts; let kindness be."),
("brevity","LATIN ORIGIN",[("brevis","short","短的","a short ruler"),("-ity","the quality of","…的性質","a small speech bubble")],("the quality of being short → briefness","簡短；簡潔"),"at a school assembly a student gives a speech with one tiny note card that says 'Thank you!' while a long scroll lies unused.","Short and sweet, the point is made,","Brevity will never fade."),
("perquisite","LATIN ORIGIN",[("per-","thoroughly","徹底地","a magnifying glass sweeping"),("quaerere","to seek, obtain","尋求、取得","a hand reaching for a prize")],("something gained beyond pay → a job's extra benefit","（職務上的）額外津貼；特權"),"a smiling zoo keeper gets a free ice cream and a ride on the zoo train as a job bonus, holding a badge that says 'STAFF'.","Extra treats that come with work,","A perquisite, a happy perk."),
("indigent","LATIN ORIGIN",[("indu-","within (old form of in-)","在內","a person inside a box"),("egere","to be in need","缺乏","an empty bowl")],("in need → very poor","貧窮的；貧困的"),"volunteers at a community kitchen kindly serve warm soup and bread to a family holding empty bowls on a cold day.","Empty bowls and pockets bare,","Help the indigent with care."),
("clairvoyant","FRENCH ORIGIN",[("clair","clear (Latin clarus)","清楚的","a shining light bulb"),("voyant","seeing (Latin videre)","看見","an eye looking through a crystal ball")],("seeing clearly → seeing the future","有預知能力的；有超人洞察力的"),"a fortune teller cat gazes into a crystal ball and sees tomorrow's pop quiz, while a student leans in, amazed.","Clear she sees what's yet to be,","Clairvoyant eyes the future see."),
]
